#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    long long n;
    cin >> n;
    vector<long long> buckets[11];
    long long sum_buckets[11] = {0};
    const long long MOD_A = 998244353, MOD_B = 1000000007;
    long long counter = 0, temp_counter = 0, answer = 0;

    auto modA = [&](long long x) {
        return (x % MOD_A + MOD_A) % MOD_A;
    };

    function<void(int, long long)> fill1 = [&](int level, long long val) {
        if (val > n) return;
        if (level > 6) return;
        ++counter;
        buckets[level].push_back(modA(counter - val));
        sum_buckets[level] += modA(counter - val);
        for (int digit = 0; digit < 10; ++digit) {
            fill1(level + 1, val * 10 + digit);
        }
    };

    function<void(int, long long)> fill2 = [&](int level, long long val) {
        if (val > n) return;
        if (level >= 1) {
            if (val * 10 * n > n && val * n + n - 1 <= n) {
                for (int i = 0; i <= 6; ++i) {
                    long long v = modA(counter - val);
                    auto &vec = buckets[i];
                    auto pos = lower_bound(vec.begin(), vec.end(), MOD_A - v) - vec.begin();
                    answer = (answer + v * (long long)vec.size() + sum_buckets[i] - MOD_A * ((long long)vec.size() - pos)) % MOD_B;
                }
                counter += temp_counter;
                return;
            }
            ++counter;
            answer = (answer + modA(counter - val)) % MOD_B;
        }
        for (int digit = (level == 0 ? 1 : 0); digit <= 9; ++digit) {
            fill2(level + 1, val * 10 + digit);
        }
    };

    fill1(0, 0);
    temp_counter = counter;
    counter = 0;
    for (int i = 0; i <= 6; ++i) {
        sort(buckets[i].begin(), buckets[i].end());
    }
    fill2(0, 0);
    cout << answer << "\n";
    return 0;
}
